"use strict";

var _graphqlRelay = require("graphql-relay");
var _mode = require("../mode");
var CG_COOKIE = 'jolt_mode_data=eyJjb21wYW55SWQiOiI0MiIsIm1vZGVJbnB1dCI6eyJtb2RlIjoiQ09OVEVOVF9HUk9VUCIsImlkIjoiNTcifX0=';
var LOC_COOKIE = 'jolt_mode_data=eyJjb21wYW55SWQiOiI0MiIsIm1vZGVJbnB1dCI6eyJtb2RlIjoiTE9DQVRJT04iLCJpZCI6IjU3In19';
function clearCookie() {
  document.cookie = 'jolt_mode_data=';
}
describe('getMode', function () {
  beforeAll(function () {
    return clearCookie();
  });
  afterAll(function () {
    return clearCookie();
  });
  it('should get mode', function () {
    window.modeInput = {
      mode: _mode.CONTENT_GROUP_MODE
    };
    expect((0, _mode.getMode)()).toEqual(_mode.CONTENT_GROUP_MODE);
  });
  it('should get mode from local storage', function () {
    window.modeInput = undefined;
    localStorage.setItem(_mode.LS_KEYS.MODE, _mode.CONTENT_GROUP_MODE);
    expect((0, _mode.getMode)()).toEqual(_mode.CONTENT_GROUP_MODE);
  });
  test('should get mode from cookie', function () {
    document.cookie = CG_COOKIE;
    expect((0, _mode.getMode)()).toEqual(_mode.CONTENT_GROUP_MODE);
    document.cookie = LOC_COOKIE;
    expect((0, _mode.getMode)()).toEqual(_mode.LOCATION_MODE);
  });
});
describe('isContentGroupMode', function () {
  beforeAll(function () {
    return clearCookie();
  });
  afterAll(function () {
    return clearCookie();
  });
  afterEach(function () {
    return clearCookie();
  });
  it('contentGroup', function () {
    window.modeInput = {
      mode: _mode.CONTENT_GROUP_MODE
    };
    expect((0, _mode.isContentGroupMode)()).toEqual(true);
    document.cookie = CG_COOKIE;
    expect((0, _mode.isContentGroupMode)()).toEqual(true);
  });
  it('location', function () {
    window.modeInput = {
      mode: _mode.LOCATION_MODE
    };
    expect((0, _mode.isContentGroupMode)()).toEqual(false);
    document.cookie = LOC_COOKIE;
    expect((0, _mode.isContentGroupMode)()).toEqual(false);
  });
});
describe('getModeId', function () {
  beforeAll(function () {
    return clearCookie();
  });
  afterAll(function () {
    return clearCookie();
  });
  it('contentGroup', function () {
    window.modeInput = {
      mode: _mode.CONTENT_GROUP_MODE,
      id: '1'
    };
    expect((0, _mode.getModeId)()).toEqual((0, _graphqlRelay.toGlobalId)(_mode.CONTENT_GROUP_MODE, '1'));
  });
  it('location', function () {
    window.modeInput = {
      mode: _mode.LOCATION_MODE,
      id: '2'
    };
    expect((0, _mode.getModeId)()).toEqual((0, _graphqlRelay.toGlobalId)(_mode.LOCATION_MODE, '2'));
  });
  it('should get modeId from local storage', function () {
    window.modeInput = undefined;
    localStorage.setItem(_mode.LS_KEYS.MODE_ID, '1');
    expect((0, _mode.getModeId)()).toEqual((0, _graphqlRelay.toGlobalId)(_mode.CONTENT_GROUP_MODE, '1'));
  });
  test('should get modeId from cookie', function () {
    document.cookie = LOC_COOKIE;
    expect((0, _mode.getModeId)()).toEqual((0, _graphqlRelay.toGlobalId)(_mode.LOCATION_MODE, '57'));
  });
});
describe('getModeInput', function () {
  beforeAll(function () {
    return clearCookie();
  });
  afterAll(function () {
    return clearCookie();
  });
  it('contentGroup', function () {
    window.modeInput = {
      mode: _mode.CONTENT_GROUP_MODE,
      id: '1'
    };
    expect((0, _mode.getModeInput)()).toEqual({
      id: (0, _graphqlRelay.toGlobalId)(_mode.CONTENT_GROUP_MODE, '1'),
      mode: _mode.GRAPHQL_CONTENT_GROUP_MODE
    });
  });
  it('location', function () {
    window.modeInput = {
      mode: _mode.LOCATION_MODE,
      id: '2'
    };
    expect((0, _mode.getModeInput)()).toEqual({
      id: (0, _graphqlRelay.toGlobalId)(_mode.LOCATION_MODE, '2'),
      mode: _mode.GRAPHQL_LOCATION_MODE
    });
  });
  describe('cookie structure', function () {
    beforeAll(function () {
      return clearCookie();
    });
    afterAll(function () {
      return clearCookie();
    });
    var setBadCookie = function setBadCookie(value) {
      document.cookie = "jolt_mode_data=".concat(btoa(JSON.stringify(value)));
    };
    test('should ignore cookie if modeInput is missing', function () {
      setBadCookie({
        companyId: '45'
      });
      window.modeInput = {
        mode: _mode.LOCATION_MODE,
        id: '2'
      };
      expect((0, _mode.getModeId)()).toEqual((0, _graphqlRelay.toGlobalId)(_mode.LOCATION_MODE, '2'));
    });
    test('should ignore cookie if mode is invalid', function () {
      setBadCookie({
        modeInput: {
          mode: 'Steelheart'
        }
      });
      window.modeInput = {
        mode: _mode.CONTENT_GROUP_MODE,
        id: '1'
      };
      expect((0, _mode.getModeId)()).toEqual((0, _graphqlRelay.toGlobalId)(_mode.CONTENT_GROUP_MODE, '1'));
    });
  });
});
describe('getCompanyModeId', function () {
  it('returns the current companyMode id', function () {
    // Set up a mock companyId;
    var mockCompanyId = '1337';
    // Set up the test by mocking the `window.IP.data.companyId` value
    window.IP = {
      data: {
        companyId: mockCompanyId
      }
    };

    // Call the function and store the result
    var result = (0, _mode.getCompanyModeId)();

    // Assert that the function returns the expected value
    expect(result).toEqual((0, _graphqlRelay.toGlobalId)(_mode.COMPANY_MODE, mockCompanyId));
  });
  it('returns empty string if the companyId is not available', function () {
    // Set up the test by deleting the `window.IP.data.companyId` value
    delete window.IP.data.companyId;

    // Call the function and store the result
    var result = (0, _mode.getCompanyModeId)();

    // Assert that the function returns null gloabalId
    expect(result).toEqual((0, _graphqlRelay.toGlobalId)(_mode.COMPANY_MODE, ''));
  });
});
describe('getCompanyModeInput', function () {
  it('returns the current companyMode input', function () {
    // Set up the test by mocking the `window.IP.data.companyId` value
    window.IP = {
      data: {
        companyId: 123
      }
    };

    // Call the function and store the result
    var result = (0, _mode.getCompanyModeInput)();

    // Assert that the function returns the expected value
    expect(result).toEqual({
      mode: _mode.GRAPHQL_COMPANY_MODE,
      id: (0, _mode.getCompanyModeId)()
    });
  });
});